-- 2026-10-02 — residui del canone, 1 di 4: tipi, NULL, colonne e tabelle mancanti
--
-- Contesto: dopo le patch del 02/10 ( 1400-2900 ) il DB di glisdev aveva ancora 117 differenze dal canone, misurate
-- con ~/.claude/bin/canone-vivo.py; gli altri deploy ne avranno di diverse. Questa patch e le tre che seguono non
-- elencano le differenze di un deploy: confrontano ogni deploy col canone dei file di base e correggono quello che
-- trovano, solo dove non si perde niente.
--
-- COSA FA. Riceve la lista di tutte le colonne di _010000999999.tables.sql, acl, static e reports, con la loro
-- definizione canonica, e per ogni tabella vera del database:
--
-- -# porta al tipo e al NULL del canone le colonne che li hanno diversi, con una ALTER per tabella. Non lo fa, e lo
--    scrive in @residui_colonne_note, quando il cambio potrebbe perdere dati: una stringa piu' corta del valore piu'
--    lungo presente, un decimale con meno cifre intere del valore piu' grande o con meno decimali, un intero piu'
--    piccolo, un NOT NULL su una colonna con dei NULL, un cambio di famiglia ( stringa / intero / decimale / altro ).
--    Le colonne AUTO_INCREMENT e quelle generate non si toccano ( gli id li ha gia' fatti _202610021500 );
-- -# aggiunge le colonne del canone che mancano, in fondo: le rimette in ordine _202610023100;
-- -# crea le tabelle del canone che mancano ( su glisdev __acl_anagrafica__, __acl_attivita__, articoli_view_static,
--    offerte_attive_view_static ), copiate dai file di base;
-- -# toglie contenuti.destinatario_nome e destinatario_numero, che nessun file di base dichiara e nessun codice legge,
--    solo se sono vuote, e l'indice mailing_mail.unica_mail, che nessun file di base dichiara.
--
-- Decisioni di Fabio del 02/10/2026 che arrivano qui: le dimensioni degli articoli sono decimal(12,5) ( i deploy avevano
-- (7,2), il canone dal 2025 (9,5), che restringeva la parte intera: (12,5) contiene tutti e due ); gli id_* sono sempre
-- DEFAULT NULL.
--
-- MariaDB ricopia la tabella a ogni ALTER che cambia un tipo: va applicata fuori orario. IDEMPOTENTE: una seconda
-- esecuzione non trova niente da fare.

-- | 202610023000

DROP TABLE IF EXISTS `__patch_residui_colonne__`;

-- | 202610023001

CREATE TABLE `__patch_residui_colonne__` (
  `tabella` char(64) NOT NULL,
  `posizione` int(11) NOT NULL,
  `colonna` char(64) NOT NULL,
  `definizione` varchar(1000) NOT NULL,
  `tipo_colonna` varchar(500) NOT NULL,
  `tipo` char(16) NOT NULL,
  `lunghezza` bigint(20) DEFAULT NULL,
  `precisione` int(11) DEFAULT NULL,
  `scala` int(11) DEFAULT NULL,
  `nullabile` char(3) NOT NULL,
  PRIMARY KEY (`tabella`, `colonna`),
  KEY `posizione` (`tabella`, `posizione`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

