-- | 202610023030

-- le famiglie dei tipi: un cambio dentro la stessa famiglia si controlla, fra famiglie diverse si fa a mano
CREATE OR REPLACE FUNCTION `__patch_residui_famiglia__`( t CHAR(16) CHARACTER SET utf8 COLLATE utf8_general_ci )
RETURNS CHAR(16) CHARACTER SET utf8 COLLATE utf8_general_ci DETERMINISTIC
RETURN CASE
    WHEN t IN ( 'char', 'varchar', 'tinytext', 'text', 'mediumtext', 'longtext' ) THEN 'stringa'
    WHEN t IN ( 'tinyint', 'smallint', 'mediumint', 'int', 'bigint' ) THEN 'intero'
    ELSE t
END;

-- | 202610023031

CREATE OR REPLACE FUNCTION `__patch_residui_rango__`( t CHAR(16) CHARACTER SET utf8 COLLATE utf8_general_ci )
RETURNS INT DETERMINISTIC
RETURN FIELD( t, 'tinyint', 'smallint', 'mediumint', 'int', 'bigint' );

-- | 202610023032

CREATE OR REPLACE PROCEDURE `__patch_residui_colonne__`()
BEGIN

    DECLARE fine INT DEFAULT 0;
    DECLARE errore INT DEFAULT 0;
    DECLARE messaggio TEXT DEFAULT NULL;
    DECLARE v_tabella, v_colonna CHAR(64) CHARACTER SET utf8 COLLATE utf8_general_ci;
    DECLARE v_tipo_colonna, a_tipo_colonna VARCHAR(500) CHARACTER SET utf8 COLLATE utf8_general_ci;
    DECLARE v_definizione VARCHAR(1000) CHARACTER SET utf8 COLLATE utf8_general_ci;
    DECLARE v_tipo, a_tipo CHAR(16) CHARACTER SET utf8 COLLATE utf8_general_ci;
    DECLARE v_lunghezza, a_lunghezza BIGINT;
    DECLARE v_precisione, v_scala, a_precisione, a_scala, v_posizione INT;
    DECLARE v_nullabile, a_nullabile CHAR(3) CHARACTER SET utf8 COLLATE utf8_general_ci;
    DECLARE a_extra VARCHAR(255) CHARACTER SET utf8 COLLATE utf8_general_ci;
    DECLARE v_corrente CHAR(64) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL;
    DECLARE v_vera INT DEFAULT 0;
    DECLARE v_clausole TEXT DEFAULT NULL;
    DECLARE v_motivo VARCHAR(255) CHARACTER SET utf8 COLLATE utf8_general_ci;

    DECLARE lista CURSOR FOR
        SELECT `tabella`, `posizione`, `colonna`, `definizione`, `tipo_colonna`, `tipo`, `lunghezza`, `precisione`, `scala`, `nullabile`
        FROM `__patch_residui_colonne__`
        ORDER BY `tabella`, `posizione`;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET fine = 1;

    SET @residui_controlli = @@foreign_key_checks;
    SET @residui_colonne_alter = 0;
    SET @residui_colonne_note = NULL;

    OPEN lista;

    ciclo: LOOP

        FETCH lista INTO v_tabella, v_posizione, v_colonna, v_definizione, v_tipo_colonna, v_tipo, v_lunghezza, v_precisione, v_scala, v_nullabile;

        -- a ogni cambio di tabella, e alla fine, si esegue la ALTER della tabella precedente
        IF fine = 1 OR v_corrente IS NULL OR v_tabella <> v_corrente THEN
            IF v_clausole IS NOT NULL THEN
                BEGIN
                    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
                        BEGIN
                            GET DIAGNOSTICS CONDITION 1 messaggio = MESSAGE_TEXT;
                            SET errore = 1;
                        END;
                    SET errore = 0;
                    SET foreign_key_checks = 0;
                    SET @residui_sql = CONCAT( 'ALTER TABLE `', v_corrente, '` ', v_clausole );
                    PREPARE modifica FROM @residui_sql;
                    EXECUTE modifica;
                    DEALLOCATE PREPARE modifica;
                    SET foreign_key_checks = @residui_controlli;
                    IF errore = 1 THEN
                        SET @residui_colonne_note = CONCAT_WS( '\n', @residui_colonne_note, LEFT( CONCAT( v_corrente, ': ALTER fallita, ', messaggio ), 500 ) );
                    ELSE
                        SET @residui_colonne_alter = @residui_colonne_alter + 1;
                    END IF;
                END;
            END IF;
            IF fine = 1 THEN
                LEAVE ciclo;
            END IF;
            SET v_corrente = v_tabella, v_clausole = NULL;
            SET v_vera = ( SELECT count(*) FROM information_schema.TABLES
                WHERE TABLE_SCHEMA = database() AND TABLE_NAME = v_tabella AND TABLE_TYPE = 'BASE TABLE' );
        END IF;

        IF v_vera = 1 THEN

            SET a_tipo = NULL, a_tipo_colonna = NULL, a_lunghezza = NULL, a_precisione = NULL, a_scala = NULL, a_nullabile = NULL, a_extra = NULL, v_motivo = NULL;
            SELECT DATA_TYPE, COLUMN_TYPE, CHARACTER_MAXIMUM_LENGTH, NUMERIC_PRECISION, NUMERIC_SCALE, IS_NULLABLE, EXTRA
                INTO a_tipo, a_tipo_colonna, a_lunghezza, a_precisione, a_scala, a_nullabile, a_extra
                FROM information_schema.COLUMNS
                WHERE TABLE_SCHEMA = database() AND TABLE_NAME = v_tabella AND COLUMN_NAME = v_colonna
                LIMIT 1;
            SET fine = 0;

            IF a_tipo IS NULL THEN
                -- la colonna manca: si aggiunge in fondo
                SET v_clausole = CONCAT_WS( ', ', v_clausole, CONCAT( 'ADD COLUMN `', v_colonna, '` ', v_definizione ) );
            ELSEIF a_extra LIKE '%auto_increment%' OR a_extra LIKE '%GENERATED%' THEN
                SET v_motivo = NULL;
            ELSEIF a_tipo_colonna = v_tipo_colonna AND a_nullabile = v_nullabile THEN
                SET v_motivo = NULL;
            ELSE
                IF `__patch_residui_famiglia__`( a_tipo ) <> `__patch_residui_famiglia__`( v_tipo ) THEN
                    SET v_motivo = CONCAT( 'e'' ', a_tipo_colonna, ', il canone vuole ', v_tipo_colonna, ': cambio di tipo da fare a mano' );
                ELSEIF ( a_tipo_colonna LIKE '%unsigned%' ) <> ( v_tipo_colonna LIKE '%unsigned%' ) THEN
                    SET v_motivo = CONCAT( 'e'' ', a_tipo_colonna, ', il canone vuole ', v_tipo_colonna, ': segno diverso, da fare a mano' );
                ELSEIF `__patch_residui_famiglia__`( v_tipo ) = 'intero' AND `__patch_residui_rango__`( v_tipo ) < `__patch_residui_rango__`( a_tipo ) THEN
                    SET v_motivo = CONCAT( 'e'' ', a_tipo_colonna, ', il canone vuole ', v_tipo_colonna, ': intero piu'' piccolo, da fare a mano' );
                ELSEIF v_tipo = 'decimal' AND v_scala < a_scala THEN
                    SET v_motivo = CONCAT( 'e'' ', a_tipo_colonna, ', il canone vuole ', v_tipo_colonna, ': meno decimali, arrotonderebbe' );
                ELSEIF `__patch_residui_famiglia__`( v_tipo ) NOT IN ( 'stringa', 'intero', 'decimal' ) AND a_tipo_colonna <> v_tipo_colonna THEN
                    SET v_motivo = CONCAT( 'e'' ', a_tipo_colonna, ', il canone vuole ', v_tipo_colonna, ': da fare a mano' );
                END IF;

                -- i controlli sui dati: lunghezza, cifre intere, NULL
                IF v_motivo IS NULL AND `__patch_residui_famiglia__`( v_tipo ) = 'stringa' AND v_lunghezza < a_lunghezza THEN
                    SET @residui_valore = NULL;
                    SET @residui_sql = CONCAT( 'SELECT max( char_length( `', v_colonna, '` ) ) INTO @residui_valore FROM `', v_tabella, '`' );
                    PREPARE controllo FROM @residui_sql; EXECUTE controllo; DEALLOCATE PREPARE controllo;
                    IF @residui_valore > v_lunghezza THEN
                        SET v_motivo = CONCAT( 'e'' ', a_tipo_colonna, ', il canone vuole ', v_tipo_colonna, ', ma un valore e'' lungo ', @residui_valore );
                    END IF;
                END IF;
                IF v_motivo IS NULL AND v_tipo = 'decimal' AND ( v_precisione - v_scala ) < ( a_precisione - a_scala ) THEN
                    SET @residui_valore = NULL;
                    SET @residui_sql = CONCAT( 'SELECT max( abs( `', v_colonna, '` ) ) INTO @residui_valore FROM `', v_tabella, '`' );
                    PREPARE controllo FROM @residui_sql; EXECUTE controllo; DEALLOCATE PREPARE controllo;
                    IF @residui_valore >= pow( 10, v_precisione - v_scala ) THEN
                        SET v_motivo = CONCAT( 'e'' ', a_tipo_colonna, ', il canone vuole ', v_tipo_colonna, ', ma c''e'' il valore ', @residui_valore );
                    END IF;
                END IF;
                IF v_motivo IS NULL AND v_nullabile = 'NO' AND a_nullabile = 'YES' THEN
                    SET @residui_valore = NULL;
                    SET @residui_sql = CONCAT( 'SELECT count(*) INTO @residui_valore FROM `', v_tabella, '` WHERE `', v_colonna, '` IS NULL' );
                    PREPARE controllo FROM @residui_sql; EXECUTE controllo; DEALLOCATE PREPARE controllo;
                    IF @residui_valore > 0 THEN
                        SET v_motivo = CONCAT( 'il canone la vuole NOT NULL, ma ha ', @residui_valore, ' righe NULL' );
                    END IF;
                END IF;

                IF v_motivo IS NULL THEN
                    SET v_clausole = CONCAT_WS( ', ', v_clausole, CONCAT( 'MODIFY `', v_colonna, '` ', v_definizione ) );
                ELSE
                    SET @residui_colonne_note = CONCAT_WS( '\n', @residui_colonne_note, CONCAT( v_tabella, '.', v_colonna, ' ', v_motivo ) );
                END IF;
            END IF;

        END IF;

    END LOOP;

    CLOSE lista;

    SET foreign_key_checks = @residui_controlli;

END;

